 const expanded=JSON.parse(fs.readFileSync(expansionPath,'utf8'));
 const context='A ampliação é intencional: matérias foram incorporadas a apostilas existentes e outras receberam livros novos, incluindo lotes 10–13. A auditoria avalia se cada incorporação foi ensinada de modo coeso, referenciada e levada adiante na cadeia, sem tratar o aumento do catálogo como erro.';
 const generalPath=path.join(out,'RELATORIO_GERAL.md');let general=fs.readFileSync(generalPath,'utf8');
 general=general.replace('## Escopo e resultado\n\n','## Escopo e resultado\n\n'+context+'\n\n');
 general=general.replace(/1\. \*\*Catálogo divergente:\*\*[^\n]+/,'1. **Rastreabilidade da ampliação:** a matriz editorial ampliada examinada organiza 280 entradas: 260 da expansão anterior, 16 novas propostas e quatro cadernos existentes recatalogados. Os 401 módulos do cursinho têm destinos principais cadastrados. A existência do vínculo não comprova que o capítulo já ensine integralmente o módulo; essa verificação orienta as fichas por núcleo.');
 general=general.replace('## Cadeia e verificadores\n\n','## Cadeia e verificadores\n\n[Auditoria da ampliação e dos 401 módulos](MODULOS_CURSO_E_ENAMED.md) e [matriz estruturada dos 280 núcleos](matriz-ampliacao.json). Foram localizados artefatos candidatos em '+expanded.totals.topics_with_artifacts+' núcleos; isso não é taxa de cobertura e não autoriza considerar os demais ausentes sem busca por aliases.\n\n');
 fs.writeFileSync(generalPath,general,'utf8');
 const chainPath=path.join(out,'CADEIA_DE_PRODUCAO.md');let chainDoc=fs.readFileSync(chainPath,'utf8');
 chainDoc=chainDoc.replace('## Transições observadas\n\n','## Transições observadas\n\n'+context+'\n\n');
 chainDoc=chainDoc.replace('| Catálogo → tema | Pedido 225; painel main 260; matriz de branch 280 | Fixar versão canônica e correspondências por núcleo, incluindo consolidações; não renumerar automaticamente. |','| Ampliação → destino | Matriz editorial ampliada: 280 entradas; 401 módulos com destino principal | Usar a matriz ampliada, localizar cada conteúdo incorporado no tema existente ou na nova apostila e conferir a profundidade; preservar remissões e evitar duplicação. |');
 chainDoc=chainDoc.replace('- O gerador permite até 50 entradas por execução; a política editorial do pedido é de lotes dinâmicos até 20 e subgrupos até cinco. Aplicar o limite editorial mesmo que a ferramenta aceite mais.','- O gerador permite até 50 entradas por execução. Distinguir lotes do catálogo ampliado de grupos operacionais: o pedido estabelece filas de trabalho de até 20 com subgrupos de até cinco; isso não obriga renumerar o catálogo ampliado.');
 fs.writeFileSync(chainPath,chainDoc,'utf8');
 for(const record of records){const topics=expanded.topics.filter(t=>t.artifacts.some(a=>a.path===record.path&&a.origin==='main'));if(!topics.length)continue;
  const section='\n## Escopo ampliado: conteúdos incorporados\n\n'+context+'\n\n'+topics.map(t=>'### Núcleo '+t.number+' — '+t.title+'\n\n'+(t.expansion_instruction||'Auditar os objetivos e as aulas principais associados ao núcleo.')+'\n\nMódulos principais: '+(t.primary_modules.map(m=>m.module_id+' — '+m.title).join('; ')||'nenhum módulo principal atribuído nesta matriz')+'.\n\n[Ficha de cobertura do núcleo](../nucleos/'+String(t.number).padStart(3,'0')+'.md).').join('\n\n')+'\n';
  fs.appendFileSync(path.join(out,'pareceres',record.key+'.md'),section,'utf8');
 }
 write('resumo.json',{...stats,expanded_curriculum:expanded.totals});
 const checkpoint=JSON.parse(fs.readFileSync(path.join(out,'checkpoint.json'),'utf8'));checkpoint.authorized_expansion=true;checkpoint.expanded_curriculum=expanded.totals;checkpoint.next='Conferir o ensino de cada módulo do cursinho no destino ampliado e as competências ENAMED, completar a matriz fonte-afirmação e reparar os handoffs. Preservar conteúdos incorporados e novas apostilas dos lotes 10–13.';write('checkpoint.json',checkpoint);
